// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(0, new address[](0), new address[](0));
    }

    function testFuzz_property(bytes4 interfaceId) public {
        bool ok;
        try c.supportsInterface(interfaceId) returns (bool r) {
            ok = r;
        } catch {
            ok = false;
        }
        // General rule: any interfaceId supported by ERC165's supportsInterface
        // (i.e. type(IERC165).interfaceId) must also be supported by C,
        // and C's answer must be at least as permissive as the base ERC165 one.
        assertTrue(
            ok || interfaceId != type(IERC165).interfaceId,
            "supportsInterface must support IERC165 interface id"
        );
    }
}

