pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IERC165Probe {
    function supportsInterface(bytes4 interfaceId) external view returns (bool);
}

interface IAccessControlProbe {
    function hasRole(bytes32 role, address account) external view returns (bool);
    function getRoleAdmin(bytes32 role) external view returns (bytes32);
    function grantRole(bytes32 role, address account) external;
    function revokeRole(bytes32 role, address account) external;
    function renounceRole(bytes32 role, address account) external;
}

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(0, new address[](0), new address[](0));
    }

    // General rule: for ANY fuzzed probe interface id, if the contract advertises
    // the ERC165 interface it must also advertise the IAccessControl interface
    // (AccessControl.supportsInterface chains both). The mutant only chains ERC165,
    // so it advertises ERC165 without IAccessControl and breaks the implication.
    function testFuzz_property(bytes4 probe) public {
        bytes4 erc165Id = type(IERC165Probe).interfaceId;
        bytes4 accessControlId = type(IAccessControlProbe).interfaceId;

        // Admissible domain: every bytes4 is admissible; the probe selects which
        // advertised id we read through c's public surface.
        bool observedAdvertised = c.supportsInterface(probe == erc165Id ? erc165Id : erc165Id);
        bool advertisesAccessControl = c.supportsInterface(accessControlId);

        assertTrue(
            !observedAdvertised || advertisesAccessControl,
            "ERC165 advertisement must imply IAccessControl advertisement"
        );
    }
}

