pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(0, new address[](0), new address[](0));
    }

    function testFuzz_property(address actor) public {
        // The deployer holds TIMELOCK_ADMIN_ROLE, which administers PROPOSER_ROLE,
        // so any account can legitimately be granted PROPOSER_ROLE.
        vm.prank(address(this));
        c.grantRole(c.PROPOSER_ROLE(), actor);

        // General rule: a granted role is visible via the public hasRole getter.
        assertTrue(c.hasRole(c.PROPOSER_ROLE(), actor));
    }
}

